{"file_path":"C:\Users\cloud_user\Documents\deepseek-harness\my-dsh\.tmp\asar-extract2.cjs","content":"#!/usr/bin/env node
// Extract listed inner files from an asar into a destination directory.
// node asar-extract2.cjs <asar> <dest> <inner-path>...
'use strict';
const fs = require('fs');
const path = require('path');

const [asar, dest, ...inners] = process.argv.slice(2);
if (!asar || !dest || inners.length === 0) {
  console.error('usage: node asar-extract2.cjs <asar> <dest> <inner-path>...');
  process.exit(2);
}

const fd = fs.openSync(asar, 'r');
const head = Buffer.alloc(16);
fs.readSync(fd, head, 0, 16, 0);
const headerSize = head.readUInt32LE(4);
const jsonLen = head.readUInt32LE(12);
const headerBuf = Buffer.alloc(jsonLen);
fs.readSync(fd, headerBuf, 0, jsonLen, 16);
const header = JSON.parse(headerBuf.toString('utf8').replace(/\0+$/, ''));

fs.mkdirSync(dest, { recursive: true });
for (const inner of inners) {
  const parts = inner.replace(/^\/+/, '').split('/');
  let node = header;
  for (const p of parts) {
    if (!node.files || !node.files[p]) {
      console.error(`not found: ${inner}`);
      process.exitCode = 1;
      continue;
    }
    node = node.files[p];
  }
  if (!node || node.files || node.unpacked) {
    console.error(`skip (dir/unpacked): ${inner}`);
    continue;
  }
  const buf = Buffer.alloc(node.size);
  fs.readSync(fd, buf, 0, node.size, 8 + headerSize + Number(node.offset));
  const out = path.join(dest, parts.slice(2).join('__'));
  fs.writeFileSync(out, buf);
  console.log(`ok ${inner} -> ${out} (${node.size} bytes)`);
}
"}

