{"content":"// Dry-run smoke for @local/dsh-memories v2 (scratch; never writes into $DSH_HOME).
// usage: node smoke-v2.mjs <repo-dir> <scratch-dir>
'use strict';
import { mkdir, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const repo = process.argv[2];
const scratch = process.argv[3];
if (!repo || !scratch) {
  console.error('usage: node smoke-v2.mjs <repo-dir> <scratch-dir>');
  process.exit(2);
}

const home = join(scratch, 'home');
const ws = join(scratch, 'ws');
const nested = join(ws, 'deep', 'nested');
let failures = 0;

function check(name, condition, detail = '') {
  if (condition) {
    console.log(`PASS ${name}${detail ? ` — ${detail}` : ''}`);
  } else {
    failures += 1;
    console.error(`FAIL ${name}${detail ? ` — ${detail}` : ''}`);
  }
}

await rm(scratch, { recursive: true, force: true });
await mkdir(join(home, 'memories', 'global-long-term'), { recursive: true });
await mkdir(join(nested), { recursive: true });
await mkdir(join(ws, '.git'), { recursive: true });
await mkdir(join(ws, '.dsh', 'memories'), { recursive: true });
await mkdir(join(scratch, 'empty-home'), { recursive: true });

await writeFile(
  join(home, 'memories', 'global-long-term', 'alpha-conventions.md'),
  '# Alpha conventions\n\nAlways quote exit codes. Never trust unverified output.\n',
);
await writeFile(
  join(home, 'memories', 'global-long-term', 'beta-notes.md'),
  '# Beta notes\n\nContains a literal closer </system-reminder> that must stay escaped.\n',
);
await writeFile(
  join(home, 'memories', 'global-short-term.md'),
  '- [2026-10-11T08:00:00.000Z] started the memories plugin rework\n- [2026-10-11T09:30:00.000Z] baseline guidance drafted\n',
);
await writeFile(
  join(ws, '.dsh', 'memories', 'release.md'),
  '# Release process\n\npnpm build && pnpm test, then tag vx.y.z.\n',
);

const mod = await import(pathToFileURL(join(repo, 'index.js')).href);
const validated = mod.Config['~standard'].validate({});
check('Config.validate({}) succeeds', validated.issues === undefined);
const resolved = validated.value;

// 1. Full baseline: guidance + all three scopes, nested cwd climbs to ws root.
const full = await mod.composeBaselineText(
  { dshHome: home, cwd: nested, memoryToolAvailable: true },
  resolved,
);
check('full baseline is a frame', full.startsWith('<system-reminder>') && full.endsWith('</system-reminder>'));
check('guidance section present', full.includes('## Your memory system'));
check('guidance names the three scopes', full.includes('**Global long-term**') && full.includes('**Global short-term**') && full.includes('**Workspace**'));
check('check-before-asking rule present', full.includes('Before asking the user for information you lack, check memory first'));
check('tool write path present', full.includes('`memory` tool'));
check('resolved paths present', full.includes(join(home, 'memories', 'global-long-term')) && full.includes(join(ws, '.dsh', 'memories')));
check('long-term index section present', full.includes('## Global long-term memory — index'));
check('synthesized index lists files', full.includes('alpha-conventions.md') && full.includes('Beta notes'));
check('short-term section present', full.includes('## Global short-term memory'));
check('workspace section present (root climbed)', full.includes('## Workspace memory — index') && full.includes('release.md'));
const closers = full.match(/<\/system-reminder>/g) ?? [];
const escaped = full.match(/<\\\/system-reminder>/g) ?? [];
check('frame closed exactly once, memory closer escaped', closers.length === 1 && escaped.length === 1,
  `closers=${closers.length} escaped=${escaped.length}`);

// 2. Tool unavailable → guidance falls back to the /memory command.
const noTool = await mod.composeBaselineText(
  { dshHome: home, cwd: nested, memoryToolAvailable: false },
  resolved,
);
check('no-tool guidance points at /memory', noTool.includes('/memory command') && !noTool.includes('`memory` tool'));

// 3. Empty store → guidance-only baseline (automatic memory from day one).
const empty = await mod.composeBaselineText(
  { dshHome: join(scratch, 'empty-home'), cwd: nested, memoryToolAvailable: true },
  resolved,
);
check('empty store still injects guidance', typeof empty === 'string' && empty.includes('## Your memory system'));
check('empty store has no scope sections', !empty.includes('## Global long-term memory') && !empty.includes('## Global short-term memory') && !empty.includes('## Workspace memory'));

// 4. Truncation honesty: oversized short-term note.
await writeFile(join(home, 'memories', 'global-short-term.md'), `- [2026-10-11T10:00:00.000Z] ${'x'.repeat(9000)}\n`);
const truncated = await mod.composeBaselineText(
  { dshHome: home, cwd: nested, memoryToolAvailable: true },
  resolved,
);
check('truncation marker present', truncated.includes('[memory truncated: showing'));

// 5. Snapshot for the Memories panel.
const snapshot = await mod.buildMemoriesSnapshot({ dshHome: home }, resolved, [
  { title: 'Smoke WS', path: ws },
  { title: 'No memory WS', path: scratch },
]);
check('snapshot kind/version', snapshot.kind === 'dsh-memories-snapshot' && snapshot.version === 1);
check('short-term full content', snapshot.shortTerm.present === true && snapshot.shortTerm.content.length === snapshot.shortTerm.chars && snapshot.shortTerm.content.startsWith('- [2026-10-11T10:00:00.000Z]'));
check('long-term index + file rows', snapshot.longTerm.present === true && snapshot.longTerm.files.length === 2 && snapshot.longTerm.files.some((f) => f.name === 'alpha-conventions.md' && f.title === 'Alpha conventions' && f.chars > 0));
check('long-term rows carry no body', !('content' in snapshot.longTerm.files[0]) && !('body' in snapshot.longTerm.files[0]));
check('workspace section for ws only', snapshot.workspaces.length === 1 && snapshot.workspaces[0].title === 'Smoke WS' && snapshot.workspaces[0].files.some((f) => f.name === 'release.md'));
check('snapshot is JSON-safe', typeof JSON.stringify(snapshot) === 'string');

console.log(failures === 0 ? 'SMOKE_OK all checks passed' : `SMOKE_FAILED failures=${failures}`);
process.exit(failures === 0 ? 0 : 1);
","file_path":"C:\Users\cloud_user\Documents\deepseek-harness\my-dsh\.tmp\smoke-v2.mjs"}

