{"content":"// Static verification bar for @local/dsh-memories (scratch).
// usage: node verify-static.cjs <repo-dir>
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const repo = process.argv[2];
if (!repo) {
  console.error('usage: node verify-static.cjs <repo-dir>');
  process.exit(2);
}
let failures = 0;
const fail = (name, detail) => { failures += 1; console.error(`FAIL ${name}${detail ? ` — ${detail}` : ''}`); };
const pass = (name, detail) => console.log(`PASS ${name}${detail ? ` — ${detail}` : ''}`);

// 1. Syntax: index.js is ESM (checked by import elsewhere too); client.js is a
// classic browser script — compile it as one, never executing it.
for (const file of ['index.js', 'client.js']) {
  const source = fs.readFileSync(path.join(repo, file), 'utf8');
  try {
    new vm.Script(source, { filename: file });
    pass(`syntax ${file}`, `${source.length} chars compiled as script`);
  } catch (error) {
    fail(`syntax ${file}`, error.message);
  }
}
// index.js must additionally be a valid ES module (import/export syntax).
{
  const source = fs.readFileSync(path.join(repo, 'index.js'), 'utf8');
  try {
    new vm.SourceTextModule(source, { identifier: 'index.js' });
    pass('syntax index.js (ESM)');
  } catch (error) {
    if (/SourceTextModule requires/.test(String(error.message))) pass('syntax index.js (ESM)', 'vm.SourceTextModule unavailable; import smoke covers it');
    else fail('syntax index.js (ESM)', error.message);
  }
}

// 2. JSON.parse every .json deliverable.
for (const file of ['package.json', 'locale/en.json', 'locale/zh.json']) {
  try {
    const parsed = JSON.parse(fs.readFileSync(path.join(repo, file), 'utf8'));
    pass(`JSON.parse ${file}`, Object.keys(parsed).join(','));
  } catch (error) {
    fail(`JSON.parse ${file}`, error.message);
  }
}

// 3. Real directory listing of the deliverables.
console.log('LISTING');
for (const entry of fs.readdirSync(repo, { withFileTypes: true })) {
  const marker = entry.isDirectory() ? 'd' : '-';
  let size = '';
  if (entry.isFile()) size = ` ${fs.statSync(path.join(repo, entry.name)).size}B`;
  console.log(`  ${marker} ${entry.name}${size}`);
}

// 4. Machine-path scan over tracked deliverables: the user name, the workspace
//    root, and the profile root must not appear as path literals.
const forbidden = [process.env.USERNAME, repo, process.env.DSH_PROFILE_DIR].filter((v) => typeof v === 'string' && v.trim() !== '');
const files = fs.readdirSync(repo, { withFileTypes: true })
  .filter((e) => e.isFile())
  .map((e) => e.name)
  .filter((n) => /\.(js|json|md|yml)$/.test(n));
console.log(`SCAN forbidden=[${forbidden.map((v) => JSON.stringify(v)).join(', ')}] files=[${files.join(', ')}]`);
let hits = 0;
for (const file of files) {
  const text = fs.readFileSync(path.join(repo, file), 'utf8');
  for (const needle of forbidden) {
    // Normalized separators so 'C:\Users\x' and 'C:/Users/x' both match.
    const flatText = text.replaceAll('\\', '/').toLowerCase();
    const flatNeedle = needle.replaceAll('\\', '/').toLowerCase();
    if (flatText.includes(flatNeedle)) {
      hits += 1;
      fail(`machine-path ${file}`, `contains ${JSON.stringify(needle)}`);
    }
  }
}
if (hits === 0) pass('machine-path scan', `no forbidden literals in ${files.length} files`);

console.log(failures === 0 ? 'STATIC_OK' : `STATIC_FAILED failures=${failures}`);
process.exit(failures === 0 ? 0 : 1);
