// 6. The agent memory tool writes through the same store (temp home only).
const saved = await mod.runMemoryTool({ dshHome: home, cwd: nested }, resolved, { action: 'save', text: 'tool smoke note' });
check('tool save ok', saved.ok === true && saved.message.includes('short-term'));
const wroteLong = await mod.runMemoryTool({ dshHome: home, cwd: nested }, resolved, { action: 'long', title: 'Tool long memory', text: 'Written by the tool smoke.' });
check('tool long ok', wroteLong.ok === true && wroteLong.message.includes('tool-long-memory.md'));
const wroteWs = await mod.runMemoryTool({ dshHome: home, cwd: nested }, resolved, { action: 'workspace', title: 'Tool ws memory', text: 'Written by the tool smoke.' });
check('tool workspace ok', wroteWs.ok === true && wroteWs.message.includes(join(ws, '.dsh', 'memories')));
let toolError = 'no-throw';
try {
  await mod.runMemoryTool({ dshHome: home, cwd: nested }, resolved, { action: 'long', title: '  ', text: 'x' });
} catch (error) {
  toolError = error.message;
}
check('tool rejects missing title', toolError.includes('title'));
const { readFile: readText } = await import('node:fs/promises');
const regeneratedIndex = await readText(join(home, 'memories', 'global-long-term', 'INDEX.md'), 'utf8');
check('tool regenerated INDEX.md', regeneratedIndex.includes('Tool long memory'));
const afterTool = await mod.buildMemoriesSnapshot({ dshHome: home }, resolved, [{ title: 'Smoke WS', path: ws }]);
check('tool writes visible in snapshot', afterTool.shortTerm.content.includes('tool smoke note') && afterTool.longTerm.files.some((f) => f.name === 'tool-long-memory.md') && afterTool.workspaces[0].files.some((f) => f.name === 'tool-ws-memory.md'));

